impl AetherCryoDamageEnum {
    pub fn get_element(&self, infused: bool) -> Element {
        use AetherCryoDamageEnum::*;
        match *self {
            A1 | A2 | A3 | A4 | A5 | Z1 | Z2 | X1 | X2 | X3 => {
                if infused {
                    Element::Cryo
                } else {
                    Element::Physical
                }
            }
            _ => Element::Cryo,
        }
    }

    pub fn get_skill_type(&self) -> SkillType {
        use AetherCryoDamageEnum::*;
        match *self {
            A1 | A2 | A3 | A4 | A5 => SkillType::NormalAttack,
            Z1 | Z2 | P4A | P4B | P4T => SkillType::ChargedAttack,
            X1 => SkillType::PlungingAttackInAction,
            X2 | X3 => SkillType::PlungingAttackOnGround,
            E | E_CRYSTAL => SkillType::ElementalSkill,
            Q | Q_TOTAL => SkillType::ElementalBurst,
        }
    }

    pub fn get_elevative_type(&self, stellar_glimmer_state: StellarGlimmerState) -> Option<ElevativeReaction> {
        use AetherCryoDamageEnum::*;
        match *self {
            // 辉映·星烁状态下，元素爆发与重击·冰凝改为造成视为对应星烁反应伤害的冰元素伤害
            Q | Q_TOTAL | P4A | P4B | P4T => match stellar_glimmer_state {
                StellarGlimmerState::StellarConduct => Some(ElevativeReaction::StellarConductCryo),
                StellarGlimmerState::StellarSwirl => Some(ElevativeReaction::StellarSwirlCryo),
                _ => None,
            },
            _ => None,
        }
    }
}

